  }

  def AfterEntrypoint(): Unit = {
    Art.finalizeTest(Arch.CabinAirCareSupervisor_Instance_airCareSupervisionProcess_humidityAssessor)
  }

  def testCompute(): Unit = {
    Art.manuallyClearOutput()
    Art.testCompute(Arch.CabinAirCareSupervisor_Instance_airCareSupervisionProcess_humidityAssessor)
  }

  def testInitialise(): Unit = {
    Art.manuallyClearOutput()
    Art.testInitialise(Arch.CabinAirCareSupervisor_Instance_airCareSupervisionProcess_humidityAssessor)
  }

  /** helper function to set the values of all input ports.
   * @param cabinHumidityBand payload for data port cabinHumidityBand
   * @param humidityValidity payload for data port humidityValidity
   */
  def put_concrete_inputs(cabinHumidityBand : Cabin_Air_Care_Supervisor.CabinHumidityBand.Type,
                          humidityValidity : Cabin_Air_Care_Supervisor.HumidityValidity.Type): Unit = {
    put_cabinHumidityBand(cabinHumidityBand)
    put_humidityValidity(humidityValidity)
  }


  /** helper function to check HumidityAssessor_airCareSupervisionProcess_humidityAssessor's
   * output ports.  Use named arguments to check subsets of the output ports.
   * @param humidityAssessment method that will be called with the value of the outgoing data
   *        port 'humidityAssessment'.
   */
  def check_concrete_output(humidityAssessment: Cabin_Air_Care_Supervisor.HumidityAssessment.Type => B): Unit = {
    var testFailures: ISZ[ST] = ISZ()

    val humidityAssessmentValue: Cabin_Air_Care_Supervisor.HumidityAssessment.Type = get_humidityAssessment().get
    if(!humidityAssessment(humidityAssessmentValue)) {
      testFailures = testFailures :+ st"'humidityAssessment' did not match expected: value of the outgoing data port is ${humidityAssessmentValue}"
    }

    assert(testFailures.isEmpty, st"${(testFailures, "\n")}".render)
  }


  // setter for in DataPort
  def put_cabinHumidityBand(value : Cabin_Air_Care_Supervisor.CabinHumidityBand.Type): Unit = {
    Art.insertInInfrastructurePort(Arch.CabinAirCareSupervisor_Instance_airCareSupervisionProcess_humidityAssessor.operational_api.cabinHumidityBand_Id, Cabin_Air_Care_Supervisor.CabinHumidityBand_Payload(value))
