  // setter for in DataPort
  def put_humidityValidity(value : Cabin_Air_Care_Supervisor.HumidityValidity.Type): Unit = {
    Art.insertInInfrastructurePort(Arch.CabinAirCareSupervisor_Instance_airCareSupervisionProcess_humidityAssessor.operational_api.humidityValidity_Id, Cabin_Air_Care_Supervisor.HumidityValidity_Payload(value))
  }

  // getter for out DataPort
  def get_humidityAssessment(): Option[Cabin_Air_Care_Supervisor.HumidityAssessment.Type] = {
    val value: Option[Cabin_Air_Care_Supervisor.HumidityAssessment.Type] = get_humidityAssessment_payload() match {
      case Some(Cabin_Air_Care_Supervisor.HumidityAssessment_Payload(v)) => Some(v)
      case Some(v) => halt(s"Unexpected payload on port humidityAssessment.  Expecting 'Cabin_Air_Care_Supervisor.HumidityAssessment_Payload' but received ${v}")
      case _ => None[Cabin_Air_Care_Supervisor.HumidityAssessment.Type]()
    }
    return value
  }

  // payload getter for out DataPort
  def get_humidityAssessment_payload(): Option[Cabin_Air_Care_Supervisor.HumidityAssessment_Payload] = {
    return Art.observeOutInfrastructurePort(Arch.CabinAirCareSupervisor_Instance_airCareSupervisionProcess_humidityAssessor.initialization_api.humidityAssessment_Id).asInstanceOf[Option[Cabin_Air_Care_Supervisor.HumidityAssessment_Payload]]
